import sys

def main():
    input_data = sys.stdin.read().split()
    idx = 0
    N = 510
    mod = 10**9 + 7

    n = int(input_data[idx]); idx += 1
    m = int(input_data[idx]); idx += 1
    K = int(input_data[idx]); idx += 1

    a = [0] * N
    b = [0] * N
    A = [0] * N
    B = [0] * N

    def mult(u, v):
        z = [0] * N
        for i in range(0, 250):
            ui = u[i]
            if ui:
                for j in range(0, 250):
                    z[i + j] = (z[i + j] + ui * v[j]) % mod
        for i in range(498, 249, -1):
            zi = z[i]
            if zi:
                for j in range(1, m + 1):
                    t = i - b[j]
                    s = z[t] + zi
                    z[t] = s - mod if s >= mod else s
        for i in range(0, 250):
            u[i] = z[i]

    def ksm(c, nn):
        nonlocal A
        A = [0] * N
        A[0] = 1
        while nn:
            if nn & 1:
                mult(A, c)
            nn >>= 1
            mult(c, c)

    for i in range(1, n + 1):
        a[i] = int(input_data[idx]); idx += 1
    for i in range(1, m + 1):
        b[i] = int(input_data[idx]); idx += 1

    for i in range(1, n + 1):
        c = [0] * N
        c[1] = 1
        ksm(c, a[i])
        for j in range(0, 250):
            s = B[j] + A[j]
            B[j] = s - mod if s >= mod else s

    ksm(B, K)
    for i in range(0, 250):
        B[i] = A[i]
    for i in range(249, 0, -1):
        for j in range(1, m + 1):
            if i >= b[j]:
                t = i - b[j]
                s = B[t] + B[i]
                B[t] = s - mod if s >= mod else s
    print(B[0])

main()
